/** autogenerated **/
/**
 *
 **/
Ext._define('rh.person.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.person.Window',

    configOrderToolBar: ['person', '-', 'edit', 'remove', 'convert', 'merge', '-', 'search', '->', 'download'],

    keywordFieldMessage: 'Nome, Endereço, Telefone, CPF, RG, Razão Social, CNPJ e OAB',

    singleton: {
        classDB: [],

        register: function (name, label, iconCls, Class) {
            rh.person.Grid.classDB.push({
                name: name,
                label: label,
                iconCls: iconCls,
                Class: Class
            });
        },

        getClassByName: function (name) {
            var Class = false;

            rh.person.Grid.classDB.forEach(
                function (item) {
                    if (item.name == name) {
                        Class = item.Class;
                        return false;
                    }
                }
            );

            return Class;
        },

        getNewMenu: function (scope, filter) {
            if (rh.person.Grid.classDB.length > 0) {
                var itens = rh.person.Grid.classDB.filter(
                    function (item) {
                        if ((filter || function () { return true; })(item))
                            return true;
                    }
                );

                return itens.map(function (item) {
                    return {
                        text: item.label,
                        scope: scope,
                        iconCls: item.iconCls,
                        handler: function () {
                            this.createItem(item.Class);
                        }
                    };
                });
            }
            else
                return [
                    {
                        text: 'Nenhum tipo foi especificado',
                        enable: false
                    }
                ];
        }
    },

    getConfigActionsItems: function (cfg) {
        var menu = rh.person.Grid.superclass.getConfigActionsItems.call(this, cfg);
        menu['merge'] = {
            text: 'Unificar cadastros',
            iconCls: 'icon-core icon-core-copy',
            scope: this,
            handler: function () {
                // this.merge();
            },
            hidden: true
        };
        return menu;
    },

    getConvertAction: function (cfg) {
        if (!this._convertAction) {
            this._convertAction = Ext._create('Ext.Button', {
                text: 'Converter em',
                iconCls: 'icon-rh icon-core-person',
                menu: [
                    {
                        text: 'Pessoa Física',
                        scope: this,
                        iconCls: 'icon-rh icon-core-natural-person',
                        handler: function () {
                            var selection = this.getSelectionModel().getSelections();
                            if (selection.length > 0){
                                this.convertIn('pessoafisica', selection[0].data);
                            }else{
                                Ext.Msg.show({
                                    title: 'Converter pessoa',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: 'Necessário selecionar uma pessoa para conversão!'
                                });
                            }
                        }
                    },
                    {
                        text: 'Pessoa Juridica',
                        scope: this,
                        iconCls: 'icon-rh icon-core-legal-person',
                        handler: function () {
                            var selection = this.getSelectionModel().getSelections();
                            if (selection.length > 0){
                                this.convertIn('pessoajuridica', selection[0].data);
                            }else{
                                Ext.Msg.show({
                                    title: 'Converter pessoa',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: 'Necessário selecionar uma pessoa para conversão!'
                                });
                            }
                        }
                    }
                ]
            });
        }

        return this._convertAction;
    },

    convertInSpecificPerson: function(restful, dados) {
        var rest = Ext._create(restful);
        var mask = Ext._create('Ext.LoadMask', this.getEl(), { msg: 'Convertendo os dados...' });
        params = { pk: dados.pk, nome: dados.nome };
        rest.convertPerson(
            params,
            {
                scope: this,
                fn: function(rst) {
                    this.getStore().reload();
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Converter pessoa',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    convertIn: function (personType, person){
        Ext.Msg.show({
            title: 'Converter pessoa',
            msg: 'Tem certeza que deseja converter a pessoa selecionada?',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function(btn) {
                if(btn != 'yes') return;
                this._convertPerson(personType, person);
            }
        });
    },

    _convertPerson: function (personType, person){
        if (person.kind == "pessoa"){
            if (personType == 'pessoafisica'){
                this.convertInSpecificPerson('rh.person.naturalperson.Restful', person);
            }else{
                this.convertInSpecificPerson('rh.person.legalperson.Restful', person);
            }
            var Class = rh.person.Grid.getClassByName(personType);
            Ext._create(Class, {
                action: 'update',
                oId: person.pk,
                values: 'remote',
                params: this.getParams(),
                callback: {
                    success: {
                        scope: this,
                        fn: function () {
                            this.getStore().reload();
                        }
                    }
                }
            }).show();
        }else{
            Ext.Msg.show({
                title: 'Converter pessoa',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Selecione o tipo correto para conversão.'
            });
        }
    },

    merge: function () {
        var selection = this.getSelectionModel().getSelections();
        if (selection.length == 2) {
            var cfg = { person: [], ownerGrid: this };
            selection.map(function (item) {
                cfg.person.push({ 'pk': item.get('pk'), 'unicode': item.get('unicode') });
            });
            Ext._create('rh.person.merge.Window', cfg).show();
        } else
            Ext.Msg.show({
                title: 'Mesclar pessoas',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Selecione duas pessoas do mesmo tipo!'
            });
    },

    createItem: function (classDef) {
        var swapRestWindow = this.restWindow;
        this.restWindow = classDef;
        rh.person.Grid.superclass.createItem.call(this);
        this.restWindow = swapRestWindow;
    },

    updateItem: function (record) {
        if (record instanceof Ext.Button)
            record = undefined;

        var selected = core.nullValue(record, this.getSelectionModel().getSelected());
        if (selected && !(selected.get('can_manage_person_employee') || selected.get('can_view_person_employee'))) {
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Você não possui autorização para editar esta pessoa.'
            });
            return;
        }
        if (selected && selected.get('kind') != 'pessoa') {
            var Class = rh.person.Grid.getClassByName(selected.get('kind'));
            Ext._create(Class, {
                action: 'update',
                oId: selected.get('pk'),
                values: 'remote',
                params: this.getParams(),
                callback: {
                    success: {
                        scope: this,
                        fn: function () {
                            this.getStore().reload();
                        }
                    }
                }
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item válido para editar.'
            });
    },

    rateFillRenderer: function (value) {
        return [
            '<div style="text-align:right">',
                (value * 100).toFixed(1) + '%',
            '</div>'
        ].join('')
    },

    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    { header: '', dataIndex: 'icons', width: 35, renderer: core.rendererIconGrid },
                    { header: 'Cod', dataIndex: 'pk', width: 50, hidden: true },
                    //{ header: 'Nome', dataIndex: 'unicode', id: 'autoExpandColumn', width: 90 },
                    { header: 'Nome', dataIndex: 'nome_social', id: 'autoExpandColumn', width: 90 },
                    { header: 'Documento', dataIndex: 'document', width: 120 },
                    { header: 'Criado por', dataIndex: 'created_by_unicode', width: 120, hidden: true },
                    { header: 'Criado em', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true },
                    { header: 'Modificado por', dataIndex: 'modified_by_unicode', width: 120, hidden: true },
                    { header: 'Modificado em', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true },
                    { header: 'Tipo', dataIndex: 'verbose_kind', width: 150, hidden: false },
                    { header: 'Pode unificar', dataIndex: 'can_merge', width: 90, hidden: true, renderer: function (value) { return (value ? 'SIM' : 'NÃO'); } },
                    { header: 'Qualidade', dataIndex: 'rate_fill', width: 90, hidden: false, renderer: this.rateFillRenderer },
                ]
            );

        return this._columnModel;
    },

    getPersonAction: function (cfg) {
        if (!this._personAction) {
            var menu = rh.person.Grid.getNewMenu(this, (this.filterNewMenu || cfg.filterNewMenu));

            this._personAction = Ext._create('Ext.Button', {
                text: 'Novo',
                iconCls: 'icon-core icon-core-add',
                menu: menu
            });
        }

        return this._personAction;
    },

    personFilter: function () {
        if (!this._person)
            this._person = Ext._create('Ext.menu.CheckItem', {
                text: 'Pessoa',
                checked: true,
                hideOnClick: false,
                scope: this,
                handler: function () {
                    this.toggleKindPerson('pessoa');
                }
            });

        return this._person;
    },

    naturalPersonFilter: function () {
        if (!this._naturalPerson)
            this._naturalPerson = Ext._create('Ext.menu.CheckItem', {
                text: 'Pessoa Física',
                checked: true,
                hideOnClick: false,
                scope: this,
                handler: function () {
                    this.toggleKindPerson('pessoafisica');
                }
            });

        return this._naturalPerson;
    },

    legalPersonFilter: function () {
        if (!this._legalPerson)
            this._legalPerson = Ext._create('Ext.menu.CheckItem', {
                text: 'Pessoa Jurídica',
                checked: true,
                hideOnClick: false,
                scope: this,
                handler: function () {
                    this.toggleKindPerson('pessoajuridica');
                }
            });

        return this._legalPerson;
    },

    anonymousPersonFilter: function () {
        if (!this._anonymousPerson)
            this._anonymousPerson = Ext._create('Ext.menu.CheckItem', {
                text: 'Pessoa Anônima',
                checked: true,
                hideOnClick: false,
                scope: this,
                handler: function () {
                    this.toggleKindPerson('anonymousperson');
                }
            });

        return this._anonymousPerson;
    },

    lawyerFilter: function () {
        if (!this._lawyer)
            this._lawyer = Ext._create('Ext.menu.CheckItem', {
                text: 'Advogado',
                checked: true,
                hideOnClick: false,
                scope: this,
                handler: function () {
                    this.toggleKindPerson('lawyer');
                }
            });

        return this._lawyer;
    },

    getFilterMenu: function () {
        return [
            {
                text: 'Tipo',
                menu: [
                    this.personFilter(),
                    this.naturalPersonFilter(),
                    this.legalPersonFilter(),
                    this.anonymousPersonFilter(),
                    this.lawyerFilter(),
                    '-',
                    {
                        text: 'Desfazer todos os filtros',
                        scope: this,
                        hideOnClick: false,
                        handler: function () {
                            this.setFilter([]);
                            this.filterKindPerson = ['pessoa', 'pessoafisica', 'pessoajuridica', 'anonymousperson', 'lawyer'];
                            this.personFilter().setChecked(true);
                            this.naturalPersonFilter().setChecked(true);
                            this.legalPersonFilter().setChecked(true);
                            this.anonymousPersonFilter().setChecked(true);
                            this.lawyerFilter().setChecked(true);
                        }
                    }
                ]
            },
        ];
    },

    toggleKindPerson: function (tipo) {
        if (!this.filterKindPerson)
            this.filterKindPerson = ['pessoa', 'pessoafisica', 'pessoajuridica', 'anonymousperson', 'lawyer'];

        if (this.filterKindPerson.indexOf(tipo) >= 0)
            this.filterKindPerson.remove(tipo);
        else
            this.filterKindPerson.push(tipo);

        if (this.filterKindPerson.indexOf('lawyer') >= 0)
            this.setFilterProperty('pessoafisica__is_lawyer', true, 1000, false);
        else
            this.removeFilterProperty('pessoafisica__is_lawyer', 1000, false);

        this.setFilterProperty('kind__in', this.filterKindPerson, 1000);
    }

});

core.RestfulGrid.register(
    'rh.person.Restful',
    'rh.person.Grid'
);
